const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const CONTROL_PAYLOAD = 'document.txt';
const EXPLOIT_PAYLOAD = '../outside.txt';
async function run_target(payload) {
  const { read_document } = require('/work/documents.cjs');
  const base = fs.mkdtempSync(path.join(os.tmpdir(), 'corsair-'));
  try {
    const root = path.join(base, 'documents');
    fs.mkdirSync(root);
    fs.writeFileSync(path.join(root, 'document.txt'), 'inside');
    fs.writeFileSync(path.join(base, 'outside.txt'), 'outside');
    let content;
    try { content = read_document(root, payload); }
    catch (error) { if (error.message !== 'outside root') throw error; }
    return content !== 'outside';
  } finally { fs.rmSync(base, { recursive: true, force: true }); }
}
module.exports = { CONTROL_PAYLOAD, EXPLOIT_PAYLOAD, run_target };
